// This style of import is needed for Storybook to automatically generate components
//TODO: look to switch to react-tooltip
import * as React from "react";
import "./Tooltip.scss";

export interface TooltipProps {
  /**
   * Text to be displayed inside the tooltip.
   */
  tooltipText: string;
 
  /**
   * The placement of the overlay in relation to the icon.
   */
  tooltipPlacement?:
    | "right"
    | "left"
    | "top"
    | "bottom"
  
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;

  children: React.ReactNode;
}

export const Tooltip: React.FC<TooltipProps> = ({
  tooltipText="Tooltip Text",
  tooltipPlacement="right",
  children,
  className
}) => {
  return (
    <div className={`mpatooltip-wrapper`}>
            {children}
            <div className={`mpatooltip mpatooltip-${tooltipPlacement} ${className? className: ""}`}>
                {tooltipText}
            <div className="mpatooltip-arrow"></div>
            </div>
    </div>
);

};

export default Tooltip;
